export const EXCEL_REQUIREMENT_COUNT=EXCEL_REQUIREMENTS.length;
export const EXCEL_DEPARTMENT_CODES=Object.freeze(["FABRIC","CUTTING","ACCESSORIES","ELASTIC","DELIVERY","STITCHING","INWARD","CHECKING","IRONING","PACKING","DISPATCH","WAREHOUSE","SHOP","MARKETING","HR","ACCOUNTS"]);
export function requirementsForRole(area,department,role){
 const code=String(department||"").toUpperCase().replace("DESPATCH","DISPATCH");
 return EXCEL_REQUIREMENTS.filter(item=>item.area===area&&(area!=="Department"||item.department.toUpperCase().replace("DESPATCH","DISPATCH")===code&&item.role===role));
}
export function outstandingRequirements(){return EXCEL_REQUIREMENTS.filter(item=>item.status!=="VERIFIED_COMPLETE");}
